@startuml

class Customer {
  + VATnumber : string
  + Name : string
  + PhoneNumber : string
  + Address : string
}

class Package {
  + IdentifierCode : string
  + Weight : float
  + IsUrgent : boolean
}

class DeliveryCenter {
  + Name : string
  + Address : string
}

class Courier {
  + VATnumber : string
  + Name : string
  + PhoneNumber : string
}

Customer "1" -- "0..*" Package : sends
Customer "1" -- "0..*" Package : receives
Customer "1" -- "1" DeliveryCenter : associatedWith
DeliveryCenter "1" -- "0..*" Courier : employs
Courier "1" -- "0..*" Package : assignedTo
Package "0..*" -- "1" DeliveryCenter : routedThrough
Package "0..*" -- "1" DeliveryCenter : deliveredFrom

@enduml

